module.exports.retry = async function retry(fn, options) {
  let lastError;
  for (let attempt = 1; attempt <= options.attempts; attempt += 1) {
    try {
      return await fn();
    } catch (error) {
      lastError = error;
      if (attempt < options.attempts && options.sleep) await options.sleep(0);
    }
  }
  throw new Error("failed");
};
