module.exports.createLimiter = function createLimiter({ capacity, refillPerSec }) {
  let tokens = capacity;
  let last = null;
  return {
    allow(nowMs) {
      if (last !== null && nowMs > last) {
        const elapsedSec = (nowMs - last) / 1000;
        tokens = Math.min(capacity, tokens + elapsedSec * refillPerSec);
      }
      last = nowMs;
      if (tokens >= 1) {
        tokens -= 1;
        return true;
      }
      return false;
    },
  };
};
